# Example for page "main": draw once, then update in a loop.
# Generated by ESP UI Builder; replace the demo part with your own code.

import random
import time

import ui_display
import ui_main

ui = ui_main.UI(ui_display.create())
p = dict(ui_main.DEFAULTS)
ui.draw(p)

# Demo: add a point to "temp_day" (keeping at most 24) and time update().
name = "temp_day"
x = len(p[name]) and max(list(m)[0] for m in p[name])
while True:
    x += 1
    p[name].append({x: random.uniform(10.0, 30.0)})
    if len(p[name]) > 24:
        p[name].pop(0)
    t0 = time.ticks_us()
    ui.update(p)
    print("update: %d us, %d points" % (time.ticks_diff(time.ticks_us(), t0), len(p[name])))
    time.sleep_ms(500)
